fn recover_sender (entry : Result < (RawKey < TxNumber > , RawValue < TransactionSignedNoHash >) , DatabaseError > , rlp_buf : & mut Vec < u8 > ,) -> Result < (u64 , Address) , Box < SenderRecoveryStageError > > { let (tx_id , transaction) = entry . map_err (| e | Box :: new (SenderRecoveryStageError :: StageError (e . into ()))) ? ; let tx_id = tx_id . key () . expect ("key to be formated") ; let tx = transaction . value () . expect ("value to be formated") ; tx . transaction . encode_without_signature (rlp_buf) ; let sender = tx . signature . recover_signer_unchecked (keccak256 (rlp_buf)) . ok_or (SenderRecoveryStageError :: FailedRecovery (FailedSenderRecoveryError { tx : tx_id })) ? ; Ok ((tx_id , sender)) }